#!/usr/bin/env python3
"""
install_hook.py - 1-Click Git Pre-Commit Hook Installer
Automatically sets up verify_changes.py as a git pre-commit hook in any repo.
"""

import os
import sys

HOOK_CONTENT = """#!/bin/sh
# Auto-generated by agentic-repo-tracker
python scripts/verify_changes.py
if [ $? -ne 0 ]; then
    echo "❌ Git commit aborted by agentic-repo-tracker pre-commit guard."
    exit 1
fi
"""

def install_hook():
    git_dir = os.path.join(".", ".git")
    if not os.path.exists(git_dir):
        print("❌ Error: Not a git repository (.git folder not found).")
        return False
        
    hooks_dir = os.path.join(git_dir, "hooks")
    os.makedirs(hooks_dir, exist_ok=True)
    hook_path = os.path.join(hooks_dir, "pre-commit")
    
    with open(hook_path, "w", encoding="utf-8") as f:
        f.write(HOOK_CONTENT)
        
    try:
        # Give execution permissions on Unix/Mac
        os.chmod(hook_path, 0o755)
    except Exception:
        pass
        
    print(f"✔ Pre-commit guard hook installed successfully at: {hook_path}")
    print("  All future git commits will be automatically verified against secret leaks and docs drift!")
    return True

if __name__ == "__main__":
    install_hook()
